function validateRequest(req) {
  const url = new URL(req.destination);
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    return { valid: false, reason: 'unsupported-protocol' };
  }
  if (url.hostname.startsWith('127.0.0.1') || url.hostname === 'localhost') {
    return { valid: true, target: 'local-isolated-service' };
  }
  return { valid: false, reason: 'prohibited-external-destination' };
}
